const icon=(name,cls='')=>`<span class="icon ${cls}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.file}</svg></span>`;
