const CLIENT_PERMISSIONS=[['read','阅读已发布资料','查询公开快照、来源目录与媒体，不含待审核修改。'],['sync','增量拉取','主动读取公开内容的变更和正文，媒体仍需阅读权限。'],['feedback','上报学习反馈','显式允许上报推荐/曝光、已读、喜欢、学习记录和收藏，仅写此客户端的反馈。']];
