const permissionsOf=s=>(Array.isArray(s?.permissions)?s.permissions:['ingest','upload']).filter(p=>[...SOURCE_PERMISSIONS,...CLIENT_PERMISSIONS].some(([key])=>key===p));
const permissionTags=s=>permissionsOf(s).map(p=>`<span class="tag">${esc([...SOURCE_PERMISSIONS,...CLIENT_PERMISSIONS].find(([key])=>key===p)?.[1]||p)}</span>`).join('')||'<span class="tag">未授予权限</span>';
