function normalizeItem(raw){const c=raw.draft||{};const assets=c.assets||[];const status=raw.status||(raw.published&&raw.published.revision===raw.revision?'published':'pending');const type=kindOf(c);const size=assets.reduce((n,a)=>n+a.size,0);return {id:raw.id,title:c.title||'未命名资料',type,category:c.category||'',source:raw.source_id,status,revision:raw.revision,summary:c.summary||'',content:c.content||'',author:c.author||'管理员',date:dateText(raw.updated_at),updatedAt:raw.updated_at,createdAt:raw.created_at,tags:c.tags||[],url:c.url||'',assets,meta:assets.length?(type==='carousel'?assets.length+' 张卡片 · ':assets[0].name.split('.').pop().toUpperCase()+' · ')+formatBytes(size):c.url?'互联网链接':(c.content?c.content.length.toLocaleString()+' 字 · ':'')+(c.format==='markdown'?'Markdown 文章':'文本文章'),history:raw.history||[],raw}}
function remember(items){for(const raw of items){const v=normalizeItem(raw);cache.set(v.id,v)}return items.map(normalizeItem)}
function getItem(id){return detailItem?.id===id?detailItem:cache.get(id)}
function safeURL(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'#'}catch{return '#'}}
function sourceMarkup(i){const s=sourceById(i.source);return `<span class="source-cell ${s?.kind==='rss'?'rss':i.url?'web':''}"><span class="source-icon">${icon(s?.kind==='rss'?'rss':s?.system?'upload':'monitor')}</span>${esc(s?.name||'未知来源')}</span>`}
function coverArt(type){const shape={audio:'<path d="M30 54v-9a20 20 0 0 1 40 0v9" fill="none" stroke="currentColor" stroke-width="3"/><rect x="26" y="49" width="11" height="19" rx="5" fill="currentColor" opacity=".65"/><rect x="63" y="49" width="11" height="19" rx="5" fill="currentColor" opacity=".65"/><path d="M45 45v14m5-20v25m5-19v14" stroke="currentColor" stroke-width="2" stroke-linecap="round" opacity=".5"/>',video:'<rect x="23" y="28" width="54" height="43" rx="7" fill="currentColor" opacity=".14"/><rect x="27" y="32" width="46" height="35" rx="4" stroke="currentColor" fill="none" opacity=".5"/><path d="m44 39 17 10-17 10V39Z" fill="currentColor" opacity=".65"/>',article:'<rect x="31" y="20" width="41" height="58" rx="4" fill="currentColor" opacity=".18" transform="rotate(8 50 50)"/><rect x="27" y="22" width="41" height="58" rx="4" fill="#fff" opacity=".5"/><path d="M36 35h23M36 43h23M36 51h23M36 59h16M36 67h11" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" opacity=".6"/>',carousel:'<rect x="29" y="19" width="42" height="58" rx="5" fill="currentColor" opacity=".18" transform="rotate(16 50 50)"/><rect x="24" y="26" width="42" height="58" rx="5" fill="currentColor" opacity=".25" transform="rotate(-10 50 50)"/><rect x="29" y="23" width="42" height="58" rx="5" fill="#fff" opacity=".55"/><circle cx="50" cy="43" r="9" fill="currentColor" opacity=".5"/><path d="M39 62h22M44 68h12" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" opacity=".5"/>'};return `<svg viewBox="0 0 100 100" fill="none" aria-hidden="true"><circle cx="50" cy="50" r="34" stroke="currentColor" opacity=".15"/><circle cx="50" cy="50" r="45" stroke="currentColor" opacity=".08"/>${shape[type]||shape.article}</svg>`}
const cover=i=>`<div class="cover ${i.type}">${coverArt(i.type)}</div>`;
