const footer=()=>`<footer class="page-foot"><span>${icon('shield')}已连接真实服务 · 数据保存在${state.store==='file'?'本机文件存储':state.store==='memory'?'内存（重启丢失）':'PostgreSQL'} · v0.3.0</span><span><i class="dot"></i>KNOWLEDGE, WELL ORGANIZED.</span></footer>`;
