function clientInput(c){return {slug:c.slug,name:c.name,description:c.description,enabled:c.enabled,permissions:[...c.permissions]}}

const CLIENT_CONNECTION_TYPE='wzstudy.query_client';
const CLIENT_CONNECTION_VERSION=1;

function normalizeClientAddress(value){
 const text=String(value).trim();
 if(!text||/[\s\\\u0000-\u001f\u007f%?#]/u.test(text))throw new Error('请输入完整的 HTTP(S) 服务根地址，不含空格、查询参数或片段。');
 let url;try{url=new URL(text)}catch{throw new Error('服务地址无效，例如 https://study.example.com 或 http://192.168.1.10:8091。')}
 if(!['http:','https:'].includes(url.protocol)||url.username||url.password||url.pathname!=='/'||url.port==='0'||!url.hostname||['0.0.0.0','[::]','[::ffff:0:0]'].includes(url.hostname))throw new Error('仅支持 HTTP(S) 服务根地址；不要包含账号、/admin、/api/v1 或通配监听地址。');
 return url.origin;
}

function clientQrAddressHint(value){
 try{const url=new URL(normalizeClientAddress(value)),host=url.hostname;const local=host==='localhost'||host.endsWith('.localhost')||host.startsWith('127.')||host==='[::1]';return (local?'当前是回环地址，只适合同机客户端；手机扫码时它指向手机自身，请填写同一服务的可达局域网或 HTTPS 地址。 ':'')+(url.protocol==='http:'?'HTTP 不加密，请仅在可信本机/局域网使用；正式接入推荐 HTTPS。 ':'')+'仅改二维码地址不会改变服务器监听；服务若只绑定回环地址，需显式配置局域网监听与防火墙。本页不会探测或向填写的其他地址发送 Key，扫码端仍须校验目标服务。'}catch{return '请输入扫码设备可以访问的服务根地址。127.0.0.1 只代表扫码设备本身。'}
}

function renderClientQrPanel(client,manual=false){
 const eligible=client.enabled&&client.permissions?.some(p=>['read','sync'].includes(p));
 return `<section id="client-qr-panel" class="client-qr-panel" data-client-id="${esc(client.id)}"><h3>${icon('monitor')}扫码快速接入</h3><p class="field-note">二维码包含服务地址、客户端名称、ID 和查询 Key。请在支持 WzStudy 扫码协议的客户端中扫描；普通相机可能只显示文本。</p><div class="field"><label for="client-qr-url">扫码设备可访问的服务地址</label><input id="client-qr-url" type="url" value="${esc(location.origin)}" placeholder="https://study.example.com" maxlength="512" autocomplete="off" spellcheck="false"><p id="client-qr-url-hint" class="field-note">${esc(clientQrAddressHint(location.origin))}</p></div>${manual?'<div class="field"><label for="client-qr-key">已保存的此客户端查询 Key</label><input id="client-qr-key" data-connection-key type="password" maxlength="256" autocomplete="off" spellcheck="false" placeholder="粘贴已安全保存的 Key"><p class="field-note">服务端只存哈希，不能回读旧 Key。粘贴不会轮换或修改任何 Key。</p></div>':''}<label class="qr-consent"><input id="client-qr-confirm" type="checkbox"><span>我确认地址属于当前数据服务、扫码设备可访问，并知悉二维码等同于完整 Key，不公开分享。</span></label>${!eligible?'<p class="source-error">此客户端尚未启用或未授予 read/sync，不能生成可用的接入二维码，请先配置权限。</p>':''}<div class="qr-controls"><button type="button" class="btn primary small-btn" data-action="generate-client-qr" ${eligible?'':'disabled'}>${icon('monitor')}生成接入二维码</button><button type="button" id="client-qr-download" class="btn small-btn hide" data-action="download-client-qr">${icon('download')}下载二维码 PNG</button></div><p id="client-qr-status" class="field-note" role="status" aria-live="polite"></p><div id="client-qr-result" class="client-qr-result hide"><div id="client-qr-canvas"></div><p class="field-note">二维码无独立过期时间，可被重复使用；轮换 Key、停用或撤权后失效。每台设备需要独立撤销时，请分别创建客户端。</p></div></section>`;
}

function clearClientQR(panel=$('#client-qr-panel'),dispose=false){
 if(!panel)return;
 panel.dataset.generation=String((Number(panel.dataset.generation)||0)+1);
 for(const url of panel.qrObjectURLs||[])URL.revokeObjectURL(url);
 panel.qrObjectURLs?.clear();
 const canvas=panel.querySelector('canvas');if(canvas){canvas.width=0;canvas.height=0}
 panel.querySelector('#client-qr-canvas')?.replaceChildren();
 panel.querySelector('#client-qr-result')?.classList.add('hide');
 panel.querySelector('#client-qr-download')?.classList.add('hide');
 const status=panel.querySelector('#client-qr-status');if(status){status.textContent='';status.classList.remove('qr-error')}
 if(dispose){const key=panel.closest('.dialog')?.querySelector('[data-connection-key]');if(key){key.value='';key.removeAttribute('value')}}
}

function clientQrModal(client){
 if(!client)return toast('客户端状态已变化，请刷新后重试。',true);
 openModal('扫码接入客户端',esc(client.name),`<div class="info-box">${icon('shield')}<span>填写已保存的查询 Key 即可生成，不修改客户端配置。若已遗失，请显式确认轮换，旧连接将立即失效。</span></div>${renderClientQrPanel(client,true)}`,`<button class="btn danger" data-action="rotate-client" data-id="${esc(client.id)}">重新生成 Key（旧 Key 失效）</button><button class="btn" data-action="close-modal">关闭</button>`,{icon:'monitor',className:'wide'});
}

async function checkConnectionKey(key){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
 try{
  const response=await fetch('/api/v1/client/connection',{headers:{Authorization:'Bearer '+key,Accept:'application/json'},credentials:'omit',cache:'no-store',redirect:'error',signal:controller.signal});
  if(response.status===401)throw new Error('查询 Key 无效。请粘贴此客户端的完整 Key，不要使用管理员、全局只读或录入端 Key。');
  if(response.status===403)throw new Error('客户端已停用或没有查询权限，请先启用并配置 read/sync。');
  if(response.status===404)throw new Error('当前服务不支持扫码身份校验，请先更新服务。');
  if(!response.ok||!response.headers.get('Content-Type')?.includes('application/json'))throw new Error('无法验证查询 Key，请稍后重试。');
  let identity;try{identity=(await response.json()).data}catch{throw new Error('服务返回的身份响应无法解析，请检查服务或代理。')}
  if(identity?.type!==CLIENT_CONNECTION_TYPE||identity.version!==CLIENT_CONNECTION_VERSION||!identity.client_id||typeof identity.name!=='string'||!Array.isArray(identity.permissions)||!identity.permissions.length||identity.permissions.some(p=>!['read','sync','feedback'].includes(p))||!identity.permissions.some(p=>['read','sync'].includes(p)))throw new Error('服务返回的客户端身份不符合接入协议。');
  return identity;
 }catch(error){if(error.name==='AbortError')throw new Error('Key 验证超时，请检查本机服务后重试。');throw error}finally{clearTimeout(timer)}
}

async function generateClientQR(){
 const panel=$('#client-qr-panel');if(!panel)return;
 const keyInput=panel.closest('.dialog')?.querySelector('[data-connection-key]'),urlInput=panel.querySelector('#client-qr-url');
 clearClientQR(panel);
 const generation=panel.dataset.generation,epoch=authEpoch,rawURL=urlInput.value;
 let key=keyInput?.value||'';
 const current=()=>panel.isConnected&&state.authenticated&&epoch===authEpoch&&panel.dataset.generation===generation&&urlInput.value===rawURL&&keyInput?.value===key;
 const status=panel.querySelector('#client-qr-status');
 try{
  const baseURL=normalizeClientAddress(rawURL);
  if(!/^[A-Za-z0-9_-]{32,256}$/.test(key))throw new Error('请提供 32–256 位完整查询 Key，不含空格或换行。');
  if(!panel.querySelector('#client-qr-confirm').checked)throw new Error('请先确认服务地址、设备可达性及二维码的密钥风险。');
  status.textContent='正在验证此查询客户端的 Key…';
  const identity=await checkConnectionKey(key);if(!current())return;
  if(identity.client_id!==panel.dataset.clientId)throw new Error('该 Key 属于另一个客户端，未生成二维码。');
  if(!identity.name.trim()||new TextEncoder().encode(identity.name).length>200||/[\u0000-\u001f\u007f]/u.test(identity.name))throw new Error('客户端名称不符合扫码协议，请先移除控制字符并限制在 200 个 UTF-8 字节内。');
  if(baseURL.toLowerCase().includes(key.toLowerCase()))throw new Error('服务地址不得包含 Key。');
  const text=JSON.stringify({type:CLIENT_CONNECTION_TYPE,version:CLIENT_CONNECTION_VERSION,base_url:baseURL,client_id:identity.client_id,name:identity.name,access_key:key});
  const bytes=new TextEncoder().encode(text);if(bytes.length>1200)throw new Error('接入配置过长，请缩短服务地址或客户端名称。');
  let qr;try{qr=qrcodegen.QrCode.encodeSegments([qrcodegen.QrSegment.makeEci(26),qrcodegen.QrSegment.makeBytes(bytes)],qrcodegen.QrCode.Ecc.MEDIUM,1,30,-1,true)}catch{throw new Error('无法生成二维码，请检查地址和客户端名称长度。')}
  const border=4,modules=qr.size+border*2,scale=Math.max(2,Math.floor(320/modules)),ratio=Math.max(1,Math.ceil(window.devicePixelRatio||1)),canvas=document.createElement('canvas');
  canvas.width=canvas.height=modules*scale*ratio;canvas.style.width=canvas.style.height=modules*scale+'px';canvas.setAttribute('role','img');canvas.setAttribute('aria-label','查询客户端接入二维码，包含完整 Key，请勿公开分享');
  const context=canvas.getContext('2d');if(!context)throw new Error('当前浏览器无法生成二维码图像。');
  context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.fillStyle='#000000';
  for(let y=0;y<qr.size;y++)for(let x=0;x<qr.size;x++)if(qr.getModule(x,y))context.fillRect((x+border)*scale*ratio,(y+border)*scale*ratio,scale*ratio,scale*ratio);
  if(!current())return;
  panel.querySelector('#client-qr-canvas').replaceChildren(canvas);panel.querySelector('#client-qr-result').classList.remove('hide');panel.querySelector('#client-qr-download').classList.remove('hide');
  status.textContent='接入二维码已生成。请只向可信客户端展示，扫码端应校验服务身份后再保存。';
 }catch(error){if(current()){status.textContent=error.message||'二维码生成失败，请重试。';status.classList.add('qr-error')}}finally{key=''}
}

async function downloadClientQR(){
 const panel=$('#client-qr-panel'),canvas=panel?.querySelector('canvas');if(!canvas||!canvas.width)return;
 const epoch=authEpoch,generation=panel.dataset.generation;
 const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));
 if(!blob||!panel.isConnected||!state.authenticated||epoch!==authEpoch||generation!==panel.dataset.generation||panel.querySelector('canvas')!==canvas)return;
 const url=URL.createObjectURL(blob);if(!panel.qrObjectURLs)panel.qrObjectURLs=new Set();panel.qrObjectURLs.add(url);
 const anchor=document.createElement('a');anchor.href=url;anchor.download='wzstudy-client-'+panel.dataset.clientId.slice(0,8)+'.png';anchor.click();
 setTimeout(()=>{URL.revokeObjectURL(url);panel.qrObjectURLs.delete(url)},1000);
}


function clientModal(c=null){const permissions=c?.permissions||PERMISSION_PRESETS.reader;openModal(c?'配置查询客户端':'新建查询客户端','可配置阅读、增量拉取与独立反馈授权；不提供资料入库或上传权限。',`<form id="client-form" data-id="${esc(c?.id||'')}"><div class="field"><label for="client-name">客户端名称</label><input id="client-name" name="name" required maxlength="60" value="${esc(c?.name||'')}"></div><div class="field"><label for="client-desc">说明</label><textarea id="client-desc" name="description" rows="2" maxlength="1000">${esc(c?.description||'')}</textarea></div><fieldset id="client-permissions" class="permission-fieldset"><legend>查询权限</legend><div class="field"><label for="permission-preset">快捷配置</label><select id="permission-preset"><option value="custom">自定义权限</option><option value="reader" ${!c?'selected':''}>阅读 / 增量拉取</option><option value="learner">阅读 / 增量 / 学习反馈（显式授予）</option><option value="read">仅阅读</option><option value="sync">仅增量拉取</option><option value="none">不授予任何权限</option></select></div><div class="permission-grid">${CLIENT_PERMISSIONS.map(([key,label,description])=>`<label class="permission-option"><input type="checkbox" name="permissions" value="${key}" ${permissions.includes(key)?'checked':''}><span><b>${label}</b><small>${description}</small></span></label>`).join('')}</div></fieldset><div class="info-box">${icon('shield')}<span>反馈默认不授予；已有客户端需主动勾选，不自动扩权。取消全部勾选会撤销权限。Key 仅创建或轮换时返回一次；不会读取或修改录入端的 Key。</span></div><div id="form-error"></div></form>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" form="client-form" type="submit">${c?'保存配置':'创建查询客户端'}</button>`,{icon:'monitor',className:'wide'})}

async function saveClient(form){const epoch=authEpoch,fd=new FormData(form),old=state.clients.find(c=>c.id===form.dataset.id);if(form.dataset.id&&!old)return formError('客户端状态已变化，请关闭并刷新后重试；没有创建新身份。');const body={...(old?clientInput(old):{slug:'client-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)).slice(0,16),enabled:true}),name:String(fd.get('name')).trim(),description:String(fd.get('description')).trim(),permissions:fd.getAll('permissions')};if(old)body.revision=old.revision;const out=await api('/admin/clients'+(old?'/'+old.id:''),{method:old?'PUT':'POST',body});if(epoch!==authEpoch||!state.authenticated||!form.isConnected)return;closeModal();if(!old)keyModal({...out.client,kind:'query'},out.access_key);await refresh();if(old)toast('查询客户端配置已保存')}

function clientAccess(c){const id=esc(c.id),allow=p=>c.permissions.includes(p);openModal('查询客户端 Key / 接口说明',esc(c.name),`<dl class="detail-keyvalues"><dt>客户端 ID</dt><dd class="mono">${id}</dd><dt>认证</dt><dd>Authorization: Bearer &lt;查询客户端 Key&gt;</dd><dt>状态</dt><dd>${c.enabled?'已启用':'已停用'}</dd></dl><div class="client-permission-tags">${permissionTags(c)}</div><pre class="intake-code">${allow('read')?'GET /api/v1/items\nGET /api/v1/items/{id}\nGET /api/v1/sources\nGET /api/v1/media/{id}':''}${allow('sync')?'\nGET /api/v1/changes?after=0':''}${allow('feedback')?'\nPOST /api/v1/client/feedback':''}\nGET /api/v1/client/feedback\nGET /api/v1/client/feedback/events${!c.permissions.length?'\n未授予查询权限':''}</pre><div class="info-box">${icon('shield')}<span>只能读取公开快照。此 Key 不能入库、上传或管理其他身份；媒体需要阅读权限。推荐排序仍由客户端负责；经 feedback 授权可上报本客户端学习动作，用于去重。历史 Key 无法回读。</span></div>`,`<button class="btn" data-action="client-qr" data-id="${id}">扫码接入</button><button class="btn danger" data-action="rotate-client" data-id="${id}">轮换 Key</button><button class="btn" data-action="edit-client" data-id="${id}">配置权限</button><button class="btn primary" data-action="close-modal">关闭</button>`,{icon:'monitor',className:'wide'})}

function renderQuery(){return heading('数据查询','公开资料视角的 API 调试；客户端结合自身学习算法决定推荐顺序。',`<button class="btn" data-route="clients">${icon('monitor')}管理查询客户端</button>`)+renderMigrationNotice()+`<section class="panel query-panel"><form id="query-form"><div class="query-filters"><div class="field"><label for="query-q">关键词</label><input id="query-q" name="q" maxlength="150" value="${esc(queryFilters.q)}" placeholder="标题或摘要"></div><div class="field"><label for="query-kind">类型</label><select id="query-kind" name="kind"><option value="">全部类型</option>${Object.entries(TYPES).map(([k,v])=>`<option value="${k}" ${queryFilters.kind===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="query-category">分类</label><input id="query-category" name="category" maxlength="80" value="${esc(queryFilters.category)}"></div><div class="field"><label for="query-tag">标签</label><input id="query-tag" name="tag" maxlength="80" value="${esc(queryFilters.tag)}"></div><div class="field"><label for="query-source">来源</label><select id="query-source" name="source_id"><option value="">全部来源</option>${state.sources.map(s=>`<option value="${esc(s.id)}" ${queryFilters.source_id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="query-limit">每页数量</label><select id="query-limit" name="limit">${[10,20,50,100].map(n=>`<option value="${n}" ${Number(queryFilters.limit)===n?'selected':''}>${n}</option>`).join('')}</select></div>${feedbackQueryFields()}</div><div class="query-actions"><span class="muted small">使用管理员会话预览公开查询结果，不等于替某个客户端验证 Key 权限。</span><button class="btn primary" type="submit" form="query-form">${icon('search')}查询资料</button></div></form><div id="query-results">${loading()}</div></section><div class="info-box" style="margin-top:18px">${icon('info')}<span>列表分页用于浏览，不是冻结快照。可靠更新使用 GET /api/v1/changes，保存 next_cursor，并按 has_more 继续补拉。客户端可上报学习反馈用于去重；这里只保存反馈状态与事件，不计算个性化推荐。</span></div>`+footer()}

async function runQuery(form){const fd=new FormData(form);queryFilters={q:String(fd.get('q')).trim(),kind:String(fd.get('kind')),category:String(fd.get('category')).trim(),tag:String(fd.get('tag')).trim(),source_id:String(fd.get('source_id')),limit:Number(fd.get('limit')),client_id:String(fd.get('client_id')||''),exclude:fd.getAll('exclude'),exclude_since:String(fd.get('exclude_since')||'').trim()};queryPage=1;await loadQuery()}

async function loadQuery(){const seq=++queryRequest,params=new URLSearchParams({limit:queryFilters.limit,offset:(queryPage-1)*queryFilters.limit});for(const key of ['q','kind','category','tag','source_id'])if(queryFilters[key])params.set(key,queryFilters[key]);const root=$('#query-results');if(!root)return;root.setAttribute('aria-busy','true');try{let endpoint='/items';if(queryFilters.client_id){endpoint='/admin/clients/'+encodeURIComponent(queryFilters.client_id)+'/items';params.set('include_feedback','true');if(queryFilters.exclude?.length)params.set('exclude',queryFilters.exclude.join(','));if(queryFilters.exclude_since)params.set('exclude_since',queryFilters.exclude_since)}else if(queryFilters.exclude?.length||queryFilters.exclude_since){throw new Error('请先选择模拟的查询客户端；反馈不能套用到其他身份。')}const data=await api(endpoint+'?'+params);if(seq!==queryRequest||route!=='query'||!state.authenticated)return;queryResult=data;root.innerHTML=`<div class="query-endpoint mono">GET /api/v1${esc(endpoint)}?${esc(params.toString())}${queryFilters.client_id?'（管理员只读模拟该客户端反馈，不验证其 Key）':''}</div>${data.items?.length?`<div class="table-scroll"><table class="materials-table query-table"><thead><tr><th>公开资料</th><th>类型 / 分类</th><th>修订</th><th>更新时间</th><th>操作</th></tr></thead><tbody>${data.items.map(renderQueryResultRow).join('')}</tbody></table></div>`:empty('没有匹配的公开资料','待审核资料不会出现在这里；请调整筛选或先完成发布。')}<div class="pagination"><span>第 ${queryPage} 页 · 返回 ${data.items?.length||0} 条（非总量）</span><div class="page-buttons"><button class="page-button" data-action="query-page" data-value="${queryPage-1}" ${queryPage===1?'disabled':''}>上一页</button><button class="page-button" data-action="query-page" data-value="${queryPage+1}" ${!data.items?.length||data.items.length<queryFilters.limit?'disabled':''}>下一页</button></div></div><details class="query-json"><summary>查看 API 原始响应</summary><pre>${esc(JSON.stringify({data},null,2))}</pre></details>`}catch(e){if(seq===queryRequest&&route==='query'&&$('#query-results'))$('#query-results').innerHTML=empty('查询失败',esc(e.message));showError(e)}finally{if(seq===queryRequest)$('#query-results')?.removeAttribute('aria-busy')}}

function renderQueryResultRow(item){return `<tr class="query-result-row" data-query-item="${esc(item.id)}" title="点击查看公开资料详情"><td><button type="button" class="material-name text-left query-title" data-action="query-detail" data-id="${esc(item.id)}" aria-haspopup="dialog" aria-label="查看《${esc(item.title)}》的公开详情">${esc(item.title)}</button><p class="material-meta">${esc(item.summary||'暂无摘要')}</p>${queryResult?.feedback?feedbackTags(queryResult.feedback[item.id]):''}</td><td>${esc(TYPES[item.kind||'article']||item.kind)}<small>${esc(item.category||'未分类')}</small></td><td class="mono">${esc(item.revision)}</td><td>${esc(dateText(item.updated_at))}</td><td><button type="button" class="btn small-btn query-detail-button" data-action="query-detail" data-id="${esc(item.id)}" aria-haspopup="dialog">${icon('eye')}查看详情</button></td></tr>`}

async function queryDetail(id){
 if(!id||route!=='query'||!state.authenticated)return;
 const title=queryResult?.items?.find(item=>item.id===id)?.title||'正在读取公开资料';
 openModal('公开资料详情',esc(title),`<div data-query-detail-state="loading" class="loading-state" role="status" aria-live="polite"><span class="loader" aria-hidden="true"></span>正在读取公开资料…</div>`,undefined,{icon:'eye',className:'wide public-query-detail'});
 const dialog=$('#modal-root .public-query-detail'),seq=detailRequest,epoch=authEpoch;
 const current=()=>seq===detailRequest&&epoch===authEpoch&&route==='query'&&state.authenticated&&dialog.isConnected;
 try{
  const item=await api('/items/'+encodeURIComponent(id));
  if(!current())return;
  const assets=item.assets||[],kind=item.kind||'article',assetURL=a=>'/api/v1/media/'+encodeURIComponent(a.id);
  let content=kind==='article'?articleHTML(item.content||item.summary||'暂无正文'):'';
  if(['audio','video'].includes(kind)&&assets[0])content+=`<${kind} class="native-player" controls preload="metadata" src="${esc(assetURL(assets[0]))}"></${kind}>`;
  if(kind==='carousel')content+=assets.map(a=>`<img class="public-image" src="${esc(assetURL(a))}" alt="${esc(a.name)}">`).join('');
  const summary=item.summary&&(kind!=='article'||item.content&&item.content!==item.summary)?`<p class="public-detail-summary">${esc(item.summary)}</p>`:'';
  const metadata=`<dl class="detail-keyvalues public-detail-meta"><dt>资料 ID</dt><dd class="mono">${esc(item.id)}</dd><dt>来源 ID</dt><dd class="mono">${esc(item.source_id||'未提供')}</dd><dt>作者</dt><dd>${esc(item.author||'未署名')}</dd><dt>更新时间</dt><dd>${esc(dateText(item.updated_at))}</dd>${item.tags?.length?`<dt>标签</dt><dd>${item.tags.map(tag=>`<span class="tag">${esc(tag)}</span>`).join(' ')}</dd>`:''}</dl>`;
  openModal('公开资料详情',esc(item.title),`<div data-query-detail-state="ready"><div class="info-box">${icon('shield')}<span>公开修订 ${esc(item.revision)} · ${esc(TYPES[kind]||kind)} · ${esc(item.category||'未分类')}。不展示待审核修改。</span></div>${metadata}${summary}<div class="detail-content">${content||'<p class="muted">暂无可预览的正文或媒体文件，请查看原始出处。</p>'}</div>${item.url?`<a class="btn small-btn" href="${esc(safeURL(item.url))}" target="_blank" rel="noopener noreferrer">查看原始出处</a>`:''}<details class="query-json"><summary>公开 JSON</summary><pre>${esc(JSON.stringify(item,null,2))}</pre></details></div>`,undefined,{icon:'eye',className:'wide public-query-detail'});
 }catch(error){
  if(!current())return;
  openModal('公开资料详情',esc(title),`<div data-query-detail-state="error" role="alert">${empty('暂时无法打开详情',esc(error.message||'请稍后重试'))}</div>`,`<button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-action="query-detail" data-id="${esc(id)}">重新加载</button>`,{icon:'eye',className:'wide public-query-detail'});
 }
}

function renderReceipts(){return heading('入库记录','仅展示已提交的真实回执；校验失败或回滚的批次不会伪造成功记录。',`<button class="btn" data-action="reload">${icon('refresh')}刷新</button>`)+`<section class="panel receipts-panel"><div class="receipt-toolbar"><label for="receipt-source">录入来源</label><select id="receipt-source"><option value="">全部来源</option>${state.sources.map(s=>`<option value="${esc(s.id)}" ${intakeSource===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div id="intake-results">${loading()}</div></section>`+footer()}

async function loadIntakes(){const seq=++intakeRequest,params=new URLSearchParams({limit:20,offset:(intakePage-1)*20});if(intakeSource)params.set('source_id',intakeSource);try{const data=await api('/admin/intakes?'+params);if(seq!==intakeRequest||route!=='receipts'||!state.authenticated)return;const root=$('#intake-results');if(!root)return;root.innerHTML=data.items.length?`<div class="table-scroll"><table class="materials-table receipt-table"><thead><tr><th>时间 / 回执</th><th>来源 / 方式</th><th>新增</th><th>更新</th><th>未变更</th><th>本批发布</th><th>资料</th></tr></thead><tbody>${data.items.map(r=>`<tr><td>${esc(dateText(r.received_at))}<small class="mono">${esc(r.id)}</small></td><td>${esc(sourceById(r.source_id)?.name||r.source_id)}<small>${esc(INTEGRATIONS[r.integration]||r.integration)}</small></td><td>${r.created}</td><td>${r.updated}</td><td>${r.unchanged}</td><td>${r.published}</td><td>${r.items.map(i=>`<button class="text-btn" data-action="detail" data-id="${esc(i.id)}">${esc(i.id.slice(0,8))} · r${i.revision} · ${esc(({pending:'待审核',draft:'草稿',published:'已公开'})[i.status]||i.status)}</button>`).join('')}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>共 ${data.total} 条回执 · 第 ${intakePage} 页</span><div class="page-buttons"><button class="page-button" data-action="intake-page" data-value="${intakePage-1}" ${intakePage===1?'disabled':''}>上一页</button><button class="page-button" data-action="intake-page" data-value="${intakePage+1}" ${intakePage*20>=data.total?'disabled':''}>下一页</button></div></div>`:empty('暂无入库回执','新提交的资料会在同一事务中保存回执；不会伪造历史批次。')}catch(e){if(seq===intakeRequest&&route==='receipts'&&$('#intake-results'))$('#intake-results').innerHTML=empty('读取失败',esc(e.message));showError(e)}}

function renderAccess(){return heading('接入指引','三种录入方式复用同一套身份、校验、去重与回执。')+renderIntakeMethods()+`<section class="panel access-boundaries"><h2>两条链路，两个身份</h2><div class="access-columns"><article><h3>录入端 · Source Key</h3><p>采集程序、Skill、MCP 使用 wzsk_ 专用 Key。</p><pre class="intake-code">GET  /api/v1/ingest/{source_id}/status\nPOST /api/v1/ingest/{source_id}\nPOST /api/v1/ingest/{source_id}/files</pre><button class="btn small-btn" data-route="sources">管理录入端</button></article><article><h3>查询客户端 · Client Key</h3><p>学习客户端使用独立查询 Key，推荐算法在客户端运行。</p><pre class="intake-code">GET /api/v1/items\nGET /api/v1/items/{id}\nGET /api/v1/media/{id}\nGET /api/v1/changes?after=0</pre><button class="btn small-btn" data-route="clients">管理查询客户端</button></article></div><div class="info-box">${icon('shield')}<span>同一应用需要录入和查询时配置两套身份与 Key。普通录入不审批发布；入库成功不等于资料已对客户端公开。</span></div></section>`+footer()}

function collectorGuide(){openModal('采集程序 HTTP 接入','外部采集逻辑独立运行，资料通过统一接口提交。',`<ol class="guide-steps"><li>在录入端管理创建来源，保存一次性 Key。</li><li>先调用 status 检查认证与 ingest 权限。</li><li>提交 JSON 资料，或使用 multipart 上传实际媒体文件。</li><li>保存回执及资料 ID。超时先核对结果，不自动重复创建。</li></ol><pre class="intake-code">POST /api/v1/ingest/&lt;source_id&gt;\nAuthorization: Bearer &lt;录入 Key&gt;\nContent-Type: application/json\n\n{"items":[{"external_id":"lesson-001","title":"真实资料标题","kind":"article","content":"正文","url":"https://example.org/source"}]}</pre><div class="info-box">${icon('info')}<span>相同 source_id + external_id 更新同一资料。单批最多 100 条、JSON 上限 4 MiB，整批成功或回滚。响应含 receipt_id、计数及资料修订；不会向客户端分发。</span></div>`,`<button class="btn" data-action="new-source">新建录入端</button><button class="btn primary" data-action="close-modal">关闭</button>`,{icon:'code',className:'wide'})}

function mcpGuide(){const example={name:'wzstudy-ingest',transport:'stdio',command:'python',arguments:['<项目绝对路径>/mcp/wzstudy_ingest/server.py','--config','<私有录入配置路径>']};openModal('MCP 录入接入','独立 stdio 适配器，复用 HTTP/Skill 的录入客户端，不启动第二套资料库。',`<div class="info-box">${icon('shield')}<span>先创建 MCP 专用录入端，再在运行 AI 的应用中配置服务。支持只读状态检查和资料入库；文件工具仅在启动时显式提供 --allow-root 后出现。</span></div><h3 class="intake-step">服务配置模板</h3><pre class="intake-code">${esc(JSON.stringify(example,null,2))}</pre><h3 class="intake-step">私有配置内容</h3><pre class="intake-code">${esc(JSON.stringify({base_url:location.origin,source_id:'<MCP 录入来源 ID>',source_key:'<仅在本地填写录入 Key>'},null,2))}</pre><p class="intake-copy">可用工具：wzstudy_ingest_status、wzstudy_ingest_items；显式授权文件目录后增加 wzstudy_upload_files。适配器不提供查询、审核、管理或下载工具。页面不会读取密钥、自动写入 MCP 设置，也不把配置模板当作连接成功。</p><div class="info-box">${icon('info')}<span>同一请求只提交一个原子批次。工具失败会返回结构化错误；提交结果不确定时不自动重试。配置与真实资料的提交仍受 AI 应用权限控制。</span></div>`,`<button class="btn" data-action="new-mcp-source">创建 MCP 专用来源</button><button class="btn primary" data-action="close-modal">关闭</button>`,{icon:'monitor',className:'wide'})}

async function migrationModal(){const epoch=authEpoch,seq=++detailRequest;const preview=await api('/admin/identity-migration');if(epoch!==authEpoch||seq!==detailRequest||!state.authenticated)return;state.migration=preview;if(!preview.pending)return toast('没有待迁移的旧查询身份');openModal('旧身份拆分预检','先备份资料库。迁移不改资料、附件或内容游标；新生成的 Key 仅返回一次。',`<form id="migration-form"><div class="info-box">${icon('shield')}<span>${preview.pending} 个身份待迁移，${preview.mixed} 个混合 Key 必须选择保留归属。纯查询身份的旧 Key 只迁给查询客户端，旧来源 ID 保留为资料出处；不会给两个角色复制同一 Key。</span></div>${preview.entries.map(e=>`<section class="migration-entry"><h3>${esc(e.name)} <span class="tag">${e.enabled?'启用':'停用'}</span></h3><p class="mono">${esc(e.source_id)}</p><p>录入权限：${esc(e.ingest_permissions.join(' / ')||'无')}；查询权限：${esc(e.query_permissions.join(' / '))}</p>${e.requires_key_choice?`<label for="choice-${esc(e.source_id)}">旧 Key 保留在哪一侧？</label><select id="choice-${esc(e.source_id)}" data-migration-id="${esc(e.source_id)}" data-revision="${e.revision}" required><option value="">必须明确选择</option><option value="ingest">保留给录入端，为查询客户端生成新 Key</option><option value="query">保留给查询客户端，为录入端生成新 Key</option></select>`:'<p class="field-note">纯查询身份：旧 Key 迁入查询客户端，不生成重复 Key。</p>'}</section>`).join('')}<div class="field"><label><input type="checkbox" id="migration-confirm" required> 我已备份并确认身份及 Key 归属</label></div><div id="form-error"></div></form>`,`<button class="btn" data-action="close-modal">取消，不迁移</button><button class="btn danger" type="submit" form="migration-form">确认执行拆分</button>`,{icon:'shield',className:'wide'})}

async function saveMigration(){const epoch=authEpoch,form=$('#migration-form');if(!form)return;const choices=[...document.querySelectorAll('[data-migration-id]')].map(s=>({source_id:s.dataset.migrationId,revision:Number(s.dataset.revision),keep_key:s.value}));if(!$('#migration-confirm').checked||choices.some(v=>!v.keep_key))return formError('请完成备份确认并选择所有混合 Key 的归属。');const result=await api('/admin/identity-migration',{method:'POST',body:{choices}});if(epoch!==authEpoch||!state.authenticated||!form.isConnected)return;closeModal();openModal('身份拆分已提交',`已创建 ${result.converted} 个独立查询身份。`,`${result.new_keys.length?'<div class="info-box">'+icon('shield')+'<span>下面的新增 Key 仅本次显示。请立即安全保存，关闭后不能回读；原 Key 仍归属于你选择的一侧。</span></div>':''}${result.new_keys.map(k=>`<div class="field"><label>${esc(k.name)} · ${k.identity_type==='source'?'录入端新 Key':'查询客户端新 Key'}</label><input type="password" readonly class="migration-key mono" value="${esc(k.access_key)}" autocomplete="off" spellcheck="false"><button type="button" class="text-btn" data-action="reveal-migration-key">显示 / 隐藏</button></div>`).join('')||'<p>没有生成新 Key，原纯查询 Key 已迁入独立查询客户端。资料来源 ID 与内容游标未改变。</p>'}`,`<button class="btn primary" data-action="close-modal">已安全保存，关闭</button>`,{icon:'shield',className:'wide'});await refresh()}

const FEEDBACK_FLAGS=[['recommended','已推荐'],['seen','有过推荐或交互'],['read','已读'],['liked','喜欢'],['recorded','有学习记录'],['favorited','已收藏']];
const FEEDBACK_NAMES={recommended:'推荐',impression:'曝光',read:'已读',like:'喜欢',record:'学习记录',favorite:'收藏'};
function feedbackQueryFields(){return `<div class="field"><label for="query-client">模拟查询客户端（不使用其 Key）</label><select id="query-client" name="client_id"><option value="">不应用个人反馈</option>${state.clients.map(c=>`<option value="${esc(c.id)}" ${queryFilters.client_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><fieldset class="field feedback-filter"><legend>排除候选（任一匹配即排除）</legend>${FEEDBACK_FLAGS.map(([key,label])=>`<label><input type="checkbox" name="exclude" value="${key}" ${queryFilters.exclude?.includes(key)?'checked':''}>${label}</label>`).join('')}</fieldset><div class="field"><label for="query-exclude-since">仅排除此时间后的反馈（可选 RFC3339）</label><input id="query-exclude-since" name="exclude_since" maxlength="50" placeholder="2026-01-01T00:00:00Z" value="${esc(queryFilters.exclude_since||'')}"></div>`}
function feedbackTags(state){if(!state)return '';const tags=[];if(state.actions?.recommended?.count)tags.push('已推荐 '+state.actions.recommended.count+' 次');if(state.actions?.impression?.count)tags.push('曝光 '+state.actions.impression.count+' 次');for(const action of ['read','like','record','favorite'])if(state.actions?.[action]?.active)tags.push(FEEDBACK_NAMES[action]);return `<div class="feedback-tags">${tags.map(label=>`<span class="tag">${esc(label)}</span>`).join('')||'<span class="muted small">此客户端尚无反馈</span>'}</div>`}
async function clientFeedbackModal(id,offset=0){
 const client=state.clients.find(c=>c.id===id);if(!client)throw new Error('客户端已变化，请刷新重试。');
 openModal('客户端反馈记录',esc(client.name),loading(),undefined,{icon:'monitor',className:'wide client-feedback-dialog'});
 const dialog=$('#modal-root .client-feedback-dialog'),epoch=authEpoch,seq=detailRequest;
 const current=()=>dialog?.isConnected&&epoch===authEpoch&&seq===detailRequest&&state.authenticated;
 try{const data=await api('/admin/clients/'+encodeURIComponent(id)+'/feedback?limit=10&offset='+offset);if(!current())return;
 const summary=FEEDBACK_FLAGS.map(([key,label])=>`<span class="tag">${label} ${Number(data.summary?.[key]||0)}</span>`).join('');
 const body=`<div class="info-box">${icon('shield')}<span>仅查看此客户端反馈；此窗口不会上报已读、推荐或修改个人状态。排序与推荐算法仍在客户端。</span></div><div class="feedback-tags">${summary}</div><div class="small muted">${Object.entries(data.event_counts||{}).map(([key,count])=>esc(FEEDBACK_NAMES[key]||key)+'事件 '+Number(count)).join(' · ')||'暂无事件'} · 独立反馈游标 ${data.high_watermark}</div>${data.items.length?data.items.map(item=>`<section class="feedback-record"><strong class="mono">${esc(item.item_id)}</strong><small>${esc(dateText(item.updated_at))}</small>${feedbackTags(item)}${item.actions?.record?.note?`<pre class="feedback-note">${esc(item.actions.record.note)}</pre>`:''}${item.actions?.record?.progress!=null?`<p>学习进度 ${Math.round(item.actions.record.progress*100)}%</p>`:''}</section>`).join(''):empty('暂无反馈','客户端获得 feedback 授权并实际推荐或交互后按事件 ID 上报。读取候选或预览详情不会自动生成记录。')}`;
 openModal('客户端反馈记录',esc(client.name),body,`<span class="muted small">${data.total} 条资料状态</span><button class="btn" data-action="feedback-page" data-id="${esc(id)}" data-value="${Math.max(0,offset-10)}" ${offset===0?'disabled':''}>上一页</button><button class="btn" data-action="feedback-page" data-id="${esc(id)}" data-value="${offset+10}" ${offset+10>=data.total?'disabled':''}>下一页</button><button class="btn primary" data-action="close-modal">关闭</button>`,{icon:'monitor',className:'wide client-feedback-dialog'});
 }catch(error){if(current())$('#modal-root .dialog-body').innerHTML=empty('读取反馈失败',esc(error.message))}
}

async function handleAction(b){const {action,id,value}=b.dataset;if(action!=='more')closeMenu();switch(action){
 case 'upload':uploadModal();break;case 'collect':collectModal();break;case 'close-modal':requestCloseModal();break;case 'close-drawer':closeDrawer();break;case 'detail':await openDrawer(id);break;case 'edit':{const raw=await api('/admin/items/'+id);uploadModal(normalizeItem(raw));break}
 case 'status':filters.status=value;page=1;selected.clear();renderPage();await loadItems();break;case 'view':view=value;document.querySelectorAll('.view-toggle button').forEach(x=>{x.classList.toggle('active',x.dataset.value===view);x.setAttribute('aria-pressed',String(x.dataset.value===view))});updateResults();break;case 'sort':filters.sort=filters.sort==='desc'?'asc':'desc';page=1;await loadItems();b.title=filters.sort==='desc'?'最近更新优先':'最早更新优先';break;case 'page':page=Number(value);await loadItems();break;
 case 'reload-list':await loadItems();break;case 'reload':await refresh();break;case 'reset-filters':filters={status:'all',type:'all',category:'all',query:'',sort:'desc'};page=1;selected.clear();renderPage();await loadItems();break;case 'clear-selection':selected.clear();updateResults();break;case 'more':openMenu(id,b);break;
 case 'publish':await publishOne(getItem(id));break;case 'bulk-publish':await bulkPublish();break;case 'delete':deleteItems([getItem(id)]);break;case 'bulk-delete':deleteItems([...selected.values()]);break;case 'unpublish':{const i=getItem(id);confirmDialog('下架这份资料？','客户端下次增量拉取时可获知下架变更。草稿与附件仍保留，重新发布前需要提交审核。','确认下架',async()=>{await api('/admin/items/'+id+'/unpublish',{method:'POST',body:{revision:i.revision}});closeModal();await refresh();if(detailItem?.id===id)await openDrawer(id,true);toast('资料已下架')});break}
 case 'detail-tab':detailTab=value;document.querySelectorAll('.detail-tabs button').forEach(x=>{x.classList.toggle('active',x.dataset.value===value);x.setAttribute('aria-selected',String(x.dataset.value===value))});$('#detail-content').innerHTML=detailContent(detailItem);break;case 'slide':slide+=Number(value);$('#detail-content').innerHTML=detailContent(detailItem);break;
 case 'collector-guide':collectorGuide();break;case 'mcp-guide':mcpGuide();break;case 'new-mcp-source':sourceModal(null,true,'mcp');break;case 'identity-migration':await migrationModal();break;
 case 'edit-client':{const c=state.clients.find(c=>c.id===id);if(!c)return toast('客户端状态已变化，请刷新。',true);clientModal(c);}break;case 'client-access':{const c=state.clients.find(c=>c.id===id);if(!c)return toast('客户端状态已变化，请刷新后重试。',true);clientAccess(c);}break;
 case 'toggle-client':{const c=state.clients.find(c=>c.id===id);await api('/admin/clients/'+id,{method:'PUT',body:{...clientInput(c),enabled:!c.enabled,revision:c.revision}});await refresh();toast(c.enabled?'查询客户端已停用':'查询客户端已启用');break}
 case 'rotate-client':{const c=state.clients.find(c=>c.id===id);if(!c)return toast('客户端状态已变化，请刷新后重试。',true);confirmDialog('轮换查询客户端 Key？','旧查询 Key 立即失效，不影响任何录入端或其他客户端。','确认轮换',async()=>{const epoch=authEpoch,dialog=$('.dialog');const out=await api('/admin/clients/'+id+'/key',{method:'POST',body:{revision:c.revision}});if(epoch!==authEpoch||!state.authenticated||!dialog?.isConnected)return;closeModal();keyModal({...out.client,kind:'query'},out.access_key);await refresh()},true);break}
 case 'query-detail':await queryDetail(id);break;case 'query-page':queryPage=Math.max(1,Number(value)||1);await loadQuery();break;case 'intake-page':intakePage=Math.max(1,Number(value)||1);await loadIntakes();break;
 case 'reveal-migration-key':{const input=b.previousElementSibling;input.type=input.type==='password'?'text':'password';break}
 case 'new-source':sourceModal();break;case 'new-rss-source':sourceModal(null,false,'rss');break;case 'new-ai-source':sourceModal(null,true,'ai');break;case 'ai-skill':aiSkillModal(id);break;case 'manage-sources':closeModal();await navigate('sources');break;case 'new-client':clientModal();break;case 'edit-source':{const s=sourceById(id);if(!s)return toast('录入端状态已变化，请刷新。',true);sourceModal(s);}break;case 'source-access':sourceAccess(sourceById(id));break;case 'toggle-source':{const s=sourceById(id);await api('/admin/sources/'+id,{method:'PUT',body:{...sourceInput(s),enabled:!s.enabled,revision:s.revision}});await refresh();toast(s.name+(!s.enabled?'已启用':'已停用'));break}
 case 'sync-source':{try{const out=await api('/admin/sources/'+id+'/refresh',{method:'POST',body:{}});await refresh();toast(`采集完成：新增 ${out.created||0}，更新 ${out.updated||0}，未变更 ${out.unchanged||0}`)}catch(e){if(state.authenticated)await refresh();throw e}break}
 case 'rotate-source':{const s=sourceById(id);confirmDialog('轮换来源密钥？','旧密钥立即失效。请在轮换后及时更新客户端配置。','确认轮换',async()=>{const epoch=authEpoch,dialog=$('.dialog');const out=await api('/admin/sources/'+id+'/key',{method:'POST',body:{revision:s.revision}});if(epoch!==authEpoch||!state.authenticated||!dialog?.isConnected)return;closeModal();keyModal(out.source,out.access_key);await refresh()},true);break}
 case 'client-feedback':await clientFeedbackModal(id,0);break;case 'feedback-page':await clientFeedbackModal(id,Number(value)||0);break;case 'client-qr':clientQrModal(state.clients.find(c=>c.id===id));break;case 'generate-client-qr':await generateClientQR();break;case 'download-client-qr':await downloadClientQR();break;
 case 'reveal-key':{const input=$('#one-time-key');input.type=input.type==='password'?'text':'password';break}case 'copy-key':{const input=$('#one-time-key');if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(input.value);else{input.type='text';input.select();if(!document.execCommand('copy'))throw new Error('复制不可用，请手动选中并安全保存。')}toast('密钥已复制，请安全保存');break}
 case 'settings':settingsModal();break;case 'setting-toggle':b.classList.toggle('on');b.setAttribute('aria-checked',String(b.classList.contains('on')));break;case 'logout':await api('/auth/logout',{method:'POST',body:{}});cache.clear();selected.clear();showLogin('你已安全退出工作空间。');break;
 case 'help':helpModal();break;case 'notifications':notificationsModal();break;case 'review-list':filters={status:'pending',type:'all',category:'all',query:'',sort:'desc'};page=1;await navigate('library');break;case 'workspace':openModal('知序学习空间','真实数据，由服务端持久保存。',`<div class="info-box">${icon('layers')}<span>资料：${state.summary.total} 份<br>接入来源：${state.sources.filter(s=>!s.system).length} 个<br>附件占用：${formatBytes(state.summary.asset_bytes)}<br>服务版本：0.2.0</span></div>`,undefined,{icon:'layers',className:'compact'});break;
 case 'export':await exportCSV();break;case 'open-nav':document.body.classList.add('mobile-open');break;case 'close-nav':document.body.classList.remove('mobile-open');break;
}}
document.addEventListener('click',async event=>{const el=event.target;if(!(el instanceof Element))return;if(el.matches('[data-overlay="modal"]'))return requestCloseModal();if(el.matches('[data-overlay="drawer"]'))return closeDrawer();const link=el.closest('[data-route]');if(link){event.preventDefault();try{await navigate(link.dataset.route)}catch(e){showError(e)}return}const button=el.closest('[data-action]');if(button){if(button.disabled)return;const action=button.dataset.action;button.disabled=true;try{await handleAction(button)}catch(e){showError(e);if($('#form-error'))formError(e.message)}finally{if(button.isConnected)button.disabled=false}return}if(!el.closest('.context-menu'))closeMenu();const queryRow=el.closest('[data-query-item]');if(queryRow&&!el.closest('input,label,button,a,select,textarea,summary')&&!window.getSelection()?.toString()){queryRow.querySelector('.query-title')?.focus({preventScroll:true});await queryDetail(queryRow.dataset.queryItem);return}const row=el.closest('[data-item]');if(row&&!el.closest('input,label,button,a'))try{await openDrawer(row.dataset.item)}catch(e){showError(e)}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='client-qr-url'||el.matches('[data-connection-key]')){const panel=$('#client-qr-panel');clearClientQR(panel);if(panel){panel.querySelector('#client-qr-confirm').checked=false;panel.querySelector('#client-qr-url-hint').textContent=clientQrAddressHint(panel.querySelector('#client-qr-url').value)}}if(el.id==='library-search'){filters.query=el.value;page=1;selected.clear();clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadItems(),220)}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='client-qr-confirm')clearClientQR();if(el.matches('[data-select]')){const item=getItem(el.dataset.select);if(el.checked)selected.set(item.id,item);else selected.delete(item.id);updateResults()}if(el.id==='select-all'){for(const i of state.items){if(el.checked)selected.set(i.id,i);else selected.delete(i.id)}updateResults()}if(el.id==='type-filter'||el.id==='category-filter'){filters[el.id==='type-filter'?'type':'category']=el.value;page=1;selected.clear();loadItems()}if(el.id==='ai-source-select')aiSkillModal(el.value);if(el.id==='file-input')handleFiles(el.files);if(el.id==='material-type')$('#article-field').classList.toggle('hide',el.value!=='article');if(el.id==='source-kind'){const rss=el.value==='rss';$('#source-url-field').classList.toggle('hide',!rss);$('#source-url').required=rss;$('#rss-options').classList.toggle('hide',!rss);$('#rss-options').disabled=!rss;$('#client-permissions').classList.toggle('hide',rss);$('#client-permissions').disabled=rss;$('#integration-field').classList.toggle('hide',rss);$('#source-integration').disabled=rss}if(el.id==='permission-preset'){const preset=PERMISSION_PRESETS[el.value];if(preset)document.querySelectorAll('#client-permissions input[name=permissions]').forEach(input=>{input.checked=preset.includes(input.value)})}if(el.name==='permissions'&&$('#permission-preset'))$('#permission-preset').value='custom';if(el.id==='receipt-source'){intakeSource=el.value;intakePage=1;loadIntakes()}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['login-form','upload-form','collect-form','source-form','client-form','query-form','migration-form','settings-form'].includes(form.id))return;event.preventDefault();const buttons=[...document.querySelectorAll(`button[form="${form.id}"],#${form.id} button[type="submit"]`)];if(form.dataset.submitting==='true'||buttons.some(b=>b.disabled))return;form.dataset.submitting='true';const labels=buttons.map(b=>b.innerHTML);buttons.forEach(b=>{b.disabled=true;b.innerHTML='<span class="loader" aria-hidden="true"></span>'+(form.id==='query-form'?'正在查询…':'正在保存…')});try{if(form.id==='login-form'){const fd=new FormData(form);const session=await api('/auth/login',{method:'POST',body:{email:String(fd.get('email')||'').trim(),password:String(fd.get('password')||'')},quiet:true});$('#login-password').value='';state.administrator=session.administrator;state.authenticated=true;state.maxUpload=session.max_upload_bytes;const info=await api('/auth/session');state.store=info.store;document.body.classList.remove('unauthenticated');$('#login-root').innerHTML='';await refresh();return}if(form.id==='upload-form')return await saveUpload(form);if(form.id==='collect-form')return await saveLink(form);if(form.id==='source-form')return await saveSource(form);if(form.id==='client-form')return await saveClient(form);if(form.id==='query-form')return await runQuery(form);if(form.id==='migration-form')return await saveMigration();if(form.id==='settings-form'){const fd=new FormData(form);await api('/admin/settings',{method:'PUT',body:{name:String(fd.get('name')).trim(),compact:$('#setting-compact').classList.contains('on'),revision:state.settings.revision}});closeModal();await refresh();toast('数据服务设置已保存')}}catch(e){if(form.id==='login-form'&&$('#login-password'))$('#login-password').value='';if(form.id==='login-form'&&$('#login-error'))$('#login-error').innerHTML=`<div class="form-error">${esc(e.message)}</div>`;else{formError(e.message);showError(e)}}finally{if(form.isConnected)delete form.dataset.submitting;buttons.forEach((b,n)=>{if(b.isConnected){b.disabled=false;b.innerHTML=labels[n]}})}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if($('#modal-root').children.length)requestCloseModal();else if($('#context-root').children.length)closeMenu();else if($('#drawer-root').children.length)closeDrawer();else document.body.classList.remove('mobile-open');return}if(event.key==='/'&&state.authenticated&&!event.ctrlKey&&!event.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal-root').children.length&&!$('#drawer-root').children.length){event.preventDefault();if(matchMedia('(max-width:700px)').matches){navigate('library').then(()=>$('#library-search')?.focus()).catch(showError)}else $('#global-search').focus()}if(event.target.id==='global-search'&&event.key==='Enter'){event.preventDefault();filters={status:'all',type:'all',category:'all',query:event.target.value,sort:'desc'};page=1;navigate('library').then(()=>$('#library-search')?.focus()).catch(showError)}if(event.target.id==='dropzone'&&(event.key==='Enter'||event.key===' ')){event.preventDefault();$('#file-input').click()}if(event.key==='Tab'){const region=$('#modal-root .dialog')||$('#drawer-root .drawer');if(region){const focusable=[...region.querySelectorAll('button:not(:disabled),input:not([type=file]):not(:disabled),select:not(:disabled),textarea,a[href],[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}});
for(const name of ['dragenter','dragover','dragleave','drop'])document.addEventListener(name,event=>{const zone=event.target instanceof Element?event.target.closest('#dropzone'):null;if(!zone)return;event.preventDefault();zone.classList.toggle('dragging',name==='dragenter'||name==='dragover');if(name==='drop')handleFiles(event.dataTransfer.files)});
window.addEventListener('hashchange',()=>navigate(resolveRoute(location.hash.slice(1))).catch(showError));window.addEventListener('resize',closeMenu);window.addEventListener('scroll',closeMenu,{passive:true});
async function boot(){document.body.classList.add('unauthenticated');hydrate();try{const session=await api('/auth/session',{quiet:true});state.authenticated=true;state.maxUpload=session.max_upload_bytes;state.store=session.store;state.administrator=session.administrator;document.body.classList.remove('unauthenticated');await refresh()}catch(e){if(e.status===401)showLogin();else{state.authenticated=false;showLogin('无法读取工作空间：'+e.message)}}}
boot();
